var a=`1156-maple-taffy`;var r=`world-1156`;var i=`CA`;var n=`northern-america`;var o=8;var t=26;var u={en:`Maple Taffy`,ua:`Кленова карамель на снігу`};var l={en:`Maple Taffy is a dish from Canada prepared with . This is a home-scale version with measured ingredients in the individual steps where they are used. Crushed clean ice substitutes for fresh snow; candy syrup is scalding and requires care.`,ua:`Кленова карамель на снігу, страва кухні країни Канада, яку готують із таких продуктів: . Кількості в домашньому рецепті прив’язані до окремих етапів приготування. Чистий подрібнений лід замінює свіжий сніг; гарячий сироп може спричинити опіки.`};var d=[{en:`Heat pure maple syrup carefully to about 112–115°C (soft-ball stage) using a candy thermometer; syrup is extremely hot.`,ua:`Обережно нагрійте чистий кленовий сироп до приблизно 112–115°C (стадія м’якої кульки) з кондитерським термометром; сироп надзвичайно гарячий.`,t:[`sugar-syrup-cooking`],m:18,i:[[`maple-syrup`,420,`ml`]]},{en:`Crush clean ice in a shallow tray to mimic packed snow; do not add any new flavorings.`,ua:`Подрібніть чистий лід у неглибокій формі, імітуючи щільний сніг; інших додатків не потрібно.`,t:[`pressing`,`rolling-out-dough`],m:5,i:[[`ice-cubes`,500,`g`]]},{en:`Pour narrow ribbons of hot syrup over crushed ice, let cool briefly and roll onto food-safe sticks; protect hands from burns.`,ua:`Налийте тонкі смуги гарячого сиропу на колотий лід, дайте трохи охолонути й накрутіть на харчові палички; бережіть руки від опіків.`,t:[`seasoning`,`garnishing`],m:3,i:[]}];var c={slug:a,id:r,country:`CA`,region:n,servings:8,minutes:26,title:u,text:l,steps:d};export{i as country,c as default,r as id,t as minutes,n as region,o as servings,a as slug,d as steps,l as text,u as title};